    A = A_1 ∧ B = B_1 ∧ C = C_1 ∧ D = D_1

∀ {V : Type u_1} {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V} {owner : { v // G.Adj x v } → ↥D}
  {presentation : (H : ↥D) → Erdos583.PathPresentation ↑H}
  {starts : ∀ (v : { v // G.Adj x v }), Erdos583.PathStartsAt ↑(owner v) ↑v} {owner_1 : { v // G.Adj x v } → ↥D}
  {presentation_1 : (H : ↥D) → Erdos583.PathPresentation ↑H}
  {starts_1 : ∀ (v : { v // G.Adj x v }), Erdos583.PathStartsAt ↑(owner_1 v) ↑v},
  { owner := owner, presentation := presentation, starts := starts } =
      { owner := owner_1, presentation := presentation_1, starts := starts_1 } →
    owner = owner_1 ∧ presentation = presentation_1

∀ {V : Type u_1} {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V} (S : Erdos583.EndpointSelection D x)
  (fallback : ↥D) (Z : Finset V) (H : ↥D),
  S.selectedSet fallback Z H = {v | Erdos583.ChainReachable S.predecessor Z v ∧ S.totalOwner fallback v = H}

∀ {V : Type u_1} {G : SimpleGraph V} [Fintype V] {D : Finset G.Subgraph} {x : V} (S : Erdos583.EndpointSelection D x)
  (fallback : ↥D) (Z : Finset V),
  (∀ z ∈ Z, G.Adj x z) → ∀ (H : ↥D), S.selectedSet fallback Z H ⊆ {(S.presentation H).start, (S.presentation H).finish}

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (z : V) (H : ↥D),
  S.chainSelected z H =
    {v | Erdos583.ChainReachable S.predecessor {z} v ∧ ∃ (hv : G.Adj x v ∧ Odd (G.degree v)), S.owner ⟨v, hv⟩ = H}

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (z : V) (H : ↥D) {v : V},
  v ∈ S.chainSelected z H → S.predecessor v = (S.presentation H).predecessor x v

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (z : V) (H : ↥D),
  S.chainSelected z H ⊆ {(S.presentation H).start, (S.presentation H).finish}

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (z t : V) (cut : G.Subgraph),
  G.Adj x z →
    S.predecessor t = none →
      Erdos583.ChainReachable S.predecessor {z} t →
        S.exchangeEdges z cut none = cut.edgeSet ∪ if Odd (G.degree t) then ∅ else {s(x, t)}

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (v : V),
  S.exchangeOwner v = if hv : G.Adj x v ∧ Odd (G.degree v) then some (S.owner ⟨v, hv⟩) else none

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (v : V) (H : ↥D),
  S.exchangeOwner v = some H ↔ ∃ (hv : G.Adj x v ∧ Odd (G.degree v)), S.owner ⟨v, hv⟩ = H

∀ {V : Type u_1} {inst : Fintype V} {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  {owner : { v // G.Adj x v ∧ Odd (G.degree v) } → ↥D} {presentation : (H : ↥D) → Erdos583.PathPresentation ↑H}
  {starts : ∀ (v : { v // G.Adj x v ∧ Odd (G.degree v) }), Erdos583.PathStartsAt ↑(owner v) ↑v}
  {owner_1 : { v // G.Adj x v ∧ Odd (G.degree v) } → ↥D} {presentation_1 : (H : ↥D) → Erdos583.PathPresentation ↑H}
  {starts_1 : ∀ (v : { v // G.Adj x v ∧ Odd (G.degree v) }), Erdos583.PathStartsAt ↑(owner_1 v) ↑v},
  { owner := owner, presentation := presentation, starts := starts } =
      { owner := owner_1, presentation := presentation_1, starts := starts_1 } →
    owner = owner_1 ∧ presentation = presentation_1

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) {v y : V},
  S.predecessor v = some y → ∃ (hv : G.Adj x v ∧ Odd (G.degree v)), (↑(S.owner ⟨v, hv⟩)).Adj x y

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) {v : V} (hv : G.Adj x v ∧ Odd (G.degree v)),
  S.predecessor v = none ↔ x ∉ (S.presentation (S.owner ⟨v, hv⟩)).walk.support

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) {z v : V},
  G.Adj x z → ∀ (n : ℕ), (Erdos583.partialStep S.predecessor)^[n] (some z) = some v → G.Adj x v

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (z : V) (H : ↥D),
  ∃ Q, Erdos583.IsNonemptyPathSubgraph Q ∧ Q.edgeSet = (S.presentation H).selectedEdges x (S.chainSelected z H)

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (z : V) (cut : G.Subgraph) (H : ↥D),
  (S.presentation H).selectedEdges x (S.chainSelected z H) = S.exchangeEdges z cut (some H)

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.OddEndpointSelection D x) (v : V) (H : ↥D),
  (S.exchangeOwner v = some H) = ∃ (hv : G.Adj x v ∧ Odd (G.degree v)), S.owner ⟨v, hv⟩ = H

∀ {V : Type u_1} [inst : Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (self : Erdos583.OddEndpointSelection D x) (v : { v // G.Adj x v ∧ Odd (G.degree v) }),
  Erdos583.PathStartsAt ↑(self.owner v) ↑v

∀ {V : Type u_1} {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V} {owner : V → Option ↥D}
  {presentation : (H : ↥D) → Erdos583.PathPresentation ↑H} {adjacent : ∀ (v : V) (H : ↥D), owner v = some H → G.Adj x v}
  {starts : ∀ (v : V) (H : ↥D), owner v = some H → Erdos583.PathStartsAt (↑H) v} {owner_1 : V → Option ↥D}
  {presentation_1 : (H : ↥D) → Erdos583.PathPresentation ↑H}
  {adjacent_1 : ∀ (v : V) (H : ↥D), owner_1 v = some H → G.Adj x v}
  {starts_1 : ∀ (v : V) (H : ↥D), owner_1 v = some H → Erdos583.PathStartsAt (↑H) v},
  { owner := owner, presentation := presentation, adjacent := adjacent, starts := starts } =
      { owner := owner_1, presentation := presentation_1, adjacent := adjacent_1, starts := starts_1 } →
    owner = owner_1 ∧ presentation = presentation_1

∀ {V : Type u_1} [Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.PartialEndpointSelection D x) (z : V) (H : ↥D),
  ∃ Q, Erdos583.IsNonemptyPathSubgraph Q ∧ Q.edgeSet = (S.presentation H).selectedEdges x (S.selectedSet z H)

∀ {V : Type u_1} [Fintype V] {G : SimpleGraph V} {D : Finset G.Subgraph} {x : V}
  (S : Erdos583.PartialEndpointSelection D x) (z : V) (H : ↥D),
  S.selectedSet z H ⊆ {(S.presentation H).start, (S.presentation H).finish}

∀ {V : Type u_1} {G : SimpleGraph V} {H : G.Subgraph} {start finish : V} {walk : G.Walk start finish}
  {isPath : walk.IsPath} {nonempty : ¬walk.Nil} {toSubgraph_eq : walk.toSubgraph = H} {start_1 finish_1 : V}
  {walk_1 : G.Walk start_1 finish_1} {isPath_1 : walk_1.IsPath} {nonempty_1 : ¬walk_1.Nil}
  {toSubgraph_eq_1 : walk_1.toSubgraph = H},
  { start := start, finish := finish, walk := walk, isPath := isPath, nonempty := nonempty,
        toSubgraph_eq := toSubgraph_eq } =
      { start := start_1, finish := finish_1, walk := walk_1, isPath := isPath_1, nonempty := nonempty_1,
        toSubgraph_eq := toSubgraph_eq_1 } →
    start = start_1 ∧ finish = finish_1 ∧ walk ≍ walk_1

∀ {V : Type u_1} {G : SimpleGraph V} {H : G.Subgraph} (P : Erdos583.PathPresentation H) (x : V),
  G.Adj x P.finish →
    ∃ Q, Erdos583.IsNonemptyPathSubgraph Q ∧ Q.edgeSet = H.edgeSet \ P.predecessorEdges x P.finish ∪ {s(x, P.finish)}

∀ {V : Type u_1} {G : SimpleGraph V} {H : G.Subgraph} (P : Erdos583.PathPresentation H) (x : V),
  G.Adj x P.start →
    ∃ Q, Erdos583.IsNonemptyPathSubgraph Q ∧ Q.edgeSet = H.edgeSet \ P.predecessorEdges x P.start ∪ {s(x, P.start)}

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V) (a v : V),
  (Erdos583.attachLeaf G a).neighborFinset (some v) =
    if v = a then insert none (Finset.map Erdos583.someEmbedding (G.neighborFinset v))
    else Finset.map Erdos583.someEmbedding (G.neighborFinset v)

∀ {V : Type u_1} (G : SimpleGraph V) (x y : V),
  Erdos583.dkEdgeDelete G x y =
    { Adj := fun a b => G.Adj a b ∧ ¬(a = x ∧ b = y) ∧ ¬(a = y ∧ b = x), symm := ⋯, loopless := ⋯ }

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V) {x y : V} {q : ℕ}
  (P : Finset (Erdos583.dkRetainedFirstStar G x y).Subgraph),
  ((Erdos583.evenNeighbors G x).erase y).card = 3 → ¬0 < ((Erdos583.evenNeighbors G x).erase y).card → False

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V) (x z v : V),
  (Erdos583.edgeSubdivision G x z).neighborFinset (some v) =
    if v = x ∨ v = z then insert none (Finset.map Erdos583.someEmbedding ((G.deleteEdges {s(x, z)}).neighborFinset v))
    else Finset.map Erdos583.someEmbedding ((G.deleteEdges {s(x, z)}).neighborFinset v)

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V) (v : V),
  (Erdos583.parityCompletion G).neighborFinset (some v) =
    if Odd (G.degree v) then insert none (Finset.map Erdos583.someEmbedding (G.neighborFinset v))
    else Finset.map Erdos583.someEmbedding (G.neighborFinset v)

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V) (x : V) {q : ℕ}
  (D : Finset (Erdos583.starDeleteEven G x).Subgraph),
  (Erdos583.evenNeighbors G x).card = 3 → ¬0 < (Erdos583.evenNeighbors G x).card → False

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V) {x z : V},
  x ≠ z →
    ∀ (v : V),
      (Erdos583.subdivisionResidual G x z).neighborFinset (some v) =
        if v = z then insert none (Finset.map Erdos583.someEmbedding ((G.deleteEdges {s(x, z)}).neighborFinset v))
        else Finset.map Erdos583.someEmbedding ((G.deleteEdges {s(x, z)}).neighborFinset v)

∀ {V : Type u_1} [inst : Fintype V] (G : SimpleGraph V),
  Erdos583.triangleComponents G =
    {C | (Erdos583.componentVertices G C).card = 3 ∧ ∀ v ∈ Erdos583.componentVertices G C, G.degree v = 2}
